import type { OutgoingHttpHeaders, ServerResponse } from "node:http";

const SECURITY_HEADERS: OutgoingHttpHeaders = {
  "cache-control": "no-store",
  "x-content-type-options": "nosniff",
  "referrer-policy": "no-referrer",
};

/**
 * A transcript download. `fileName` is generated by us from a job id, never taken from a client.
 * `latin1` means `body` is raw file bytes, one character per byte, as DOCX export produces.
 */
export function sendDownload(res: ServerResponse, body: string, contentType: string, fileName: string, encoding?: "latin1"): void {
  const payload = encoding === "latin1" ? Buffer.from(body, "latin1") : body;
  res.writeHead(200, {
    ...SECURITY_HEADERS,
    "content-type": contentType,
    "content-disposition": `attachment; filename="${fileName}"`,
    "content-length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

export function sendNoContent(res: ServerResponse): void {
  res.writeHead(204, SECURITY_HEADERS);
  res.end();
}
